  ": les barres mesurent 22,1 − 14 = 8,1 et 18,8 − 14 = 4,8 ; la baisse dessinée vaut 3,3 ÷ 8,1 =": "The bars are 22,1 - 14 = 8,1 and 18,8 - 14 = 4,8; the drop is 3,3 ÷ 8,1 =",
  ": les coches vertes s’affichent.": ": green ticks are displayed.",
  ": les mêmes outils sur la bibliothèque de Nouakchott. Vous construisez un graphique, défendez son message, ajoutez le survol, puis reliez deux vues avec React, et vous faites relire votre graphique par une IA avec les skills de Yan Holtz. Au CM 5 : le tableau de bord complet.": "- the same tools on Nouakchott's library. You build a graph, defend its message, add the hover, then connect two views with React, and you have your graph read through an AI with Yan Holtz's skills. At CM 5: the complete dashboard.",
  ": les trois décisions (18,8 ; 13,3 ; 67,9 = 100 %), en barres horizontales, admis en couleur, titre « près d’un candidat sur cinq admis ».": "The three decisions (18,8; 13,3; 67,9 = 100%), in horizontal bars, accepted in colour, heading \"nearly one in five candidates admitted\".",
  ": linéaire, de 0 au maximum.": ": linear, from 0 at the maximum.",
  ": l’ancien standard, en plusieurs fichiers.": ": the old standard, in several files.",
  ": l’exécutif veut le « so what ? », l’analyste la méthode.": ": the executive wants the \"so what?\", the analyst the method.",
  ": l’ordre alphabétique ou le hasard obligent l’œil à chercher.": ": Alphabetical order or chance force the eye to search.",
  ": l’écart qui compte, entouré.": ": the gap that counts, surrounded.",
  ": l’œil fait des allers-retours ; les petites parts sont illisibles.": ": the eye goes back and forth; the small parts are illegible.",
  ": moins de quadrillage, plus de marqueurs, les noms au bout des courbes ; pour une courbe, l’axe peut partir de 20 °C.": ": less gridding, more markers, the names at the end of the curves; for a curve, the axis can start at 20 °C.",
  ": mon lecteur, ma règle, les nombres à 10 / 50 / 100 avis, et une adresse dont le sort change.": "My Reader, My Rule, Numbers at 10 / 50 / 100 Reviews, and an address whose spell changes.",
  ": on voit la tendance.": "We see the trend.",
