  "Attendu : autour de 788 m. Elle peut s’afficher arrondie selon les statistiques calculées.": "Expected: around 788 m. It can display rounded according to the calculated statistics.",
  "Attribute table": "Attribute table",
  "Attributs pré-attentifs": "Pre-attributes",
  "Attributs pré-attentifs.": "Pre-attentive attributes.",
  "Au CM 1, la couleur faisait sauter les 7 aux yeux. Elle n’est pas seule : chaque case cache un intrus. Qu’est-ce qui le distingue ?": "In CM 1, color made the 7s stand out. Color is not the only way: each box hides an odd one out. What makes it different?",
  "Au CM 2, le « spaghetti » : trop de lignes pour en suivre une. Ici, chaque wilaya relie 2019 à 2024. Survolez une ligne pour la sortir du lot.": "In CM 2, the spaghetti: too many lines to follow one. Here, each wilaya connects 2019 to 2024. Fly a line to get it out of the lot.",
  "Au CM 2, nous avons choisi les graphiques ; au CM 3, les cartes ; au TD 2, Bokeh a rendu votre carte survolable. Voyons comment c’est fait et à quoi ça sert. Ajoutons ce que le papier ne sait pas faire : survoler, filtrer, zoomer, relier deux vues. Fil rouge : les présidentielles 2019 et 2024, commune par commune.": "At CM 2, we chose the charts; at CM 3, the maps; at TD 2, Bokeh made your map overflyable. Let's see how it's done and what it's for. Let's add what the paper doesn't do: hover over, filter, zoom, connect two views. Red thread: presidential 2019 and 2024, common by commune.",
  "Au CM 3 : raconter avec une carte.": "At CM 3: tell with a map.",
  "Au CM 3 : « mêmes chiffres, autre histoire ». Les aplats colorient le score de Ghazouani ; les cercles comptent des voix. Basculez, survolez une wilaya.": "At CM 3: \"Same numbers, another story.\" Flats color Ghazouani's score; circles count votes. Switch over a wilaya.",
  "Au CM 4, la voiture : douze lignes qui bougent, ou un compteur et un voyant. Ici, la même idée :": "In CM 4, the car: twelve lines moving, or a meter and a light. Here, the same idea:",
  "Au CM 4, la voiture et le tableau de bord React des élections ; au TD 3, les restaurants de Nouakchott. Construisons maintenant un tableau de bord pour un lecteur qui doit décider, deux fois : sans code dans Looker Studio, puis en code avec React et D3. Fil rouge : 639 restaurants et cafés de Nouakchott.": "At CM 4, the car and the React election dashboard; at TD 3, the Nouakchott restaurants. Let's now build a dashboard for a reader who has to decide, twice: without code in Looker Studio, then in code with React and D3. Red wire: 639 restaurants and cafes in Nouakchott.",
  "Au TD 1 : le même graphique en Matplotlib, Seaborn et Altair. Venez avec Python et un notebook qui fonctionne.": "At TD 1: the same graph in Matplotlib, Seaborn and Altair. Come with Python and a notebook that works.",
  "Au TD 2 : QGIS (couches, jointure, tampon, une carte prête à publier), puis la même chaîne en code, avec GeoPandas et Bokeh.": "At TD 2: QGIS (layers, joins, buffers, a ready-to-issue map), then the same code string, with GeoPandas and Bokeh.",
  "Au TD 2, vous avez joint ce fichier aux moughataas, et Bokeh dessinait une carte qu’on survole. Reprenons-le, commune par commune. Présidentielle 2024 : Ghazouani est élu avec 56 % des voix. Un point = une commune (ou un pays, pour le vote à l’étranger). Dans": "At TD 2, you have attached this file to the moughataas, and Bokeh was drawing a map that we hover over. Let's take it back, common by commune. Presidential 2024: Ghazouani is elected with 56% of the vote. One point = a municipality (or a country, for voting abroad). In",
  "Au TD 2, vous avez joint ce fichier aux moughataas, et Bokeh dessinait une carte qu’on survole. Reprenons-le, commune par commune. Présidentielle 2024 : Ghazouani est élu avec 56 % des voix. Un point = une commune (ou un pays, pour le vote à l’étranger). Dans 20 d’entre elles, un autre candidat arrive premier. Nommez-en une.": "At TD 2, you have attached this file to the moughataas, and Bokeh drew a map that we hover over. Let's take it, common by commune. Presidential 2024: Ghazouani is elected with 56% of the vote. One point = a commune (or a country, for the foreign vote). In 20 of them, another candidate arrives first. Name one.",
  "Au TD 2, vous vous êtes demandé ce qu’il faudrait écrire sur la carte si le survol disparaissait. Voici le même graphique en deux versions. Dans la première, tout est dans l’infobulle. Dans la seconde, le message se voit sans toucher à rien. Laquelle publieriez-vous ?": "At TD 2, you wondered what you would have to write on the map if the hover disappeared. Here is the same graph in two versions. In the first, everything is in the toolbox. In the second, the message is seen without touching anything. Which one would you publish?",
  "Au TD 3": "At TD 3",
  "Au moins": "At least",
  "Au moins un carré par jour de prêt (797)": "At least one square per loan day (797)",
  "Au-delà de quelques points superposés, la densité devient illisible. La grille (ou des hexagones) montre combien il y en a. Le point reste utile pour le détail au survol.": "Beyond a few superimposed points, the density becomes unreadable. The grid (or hexagons) shows how many there are. The point remains useful for detail on the flyover.",
  "Aucun : les deux sont vrais, ils ne comptent pas les mêmes personnes": "None: both are true, they don't count the same people",
  "Aucun : un tableau de bord doit être statique": "None: a dashboard must be static",
  "Aucun avion revenu n’a d’impact sur les moteurs : ceux qui y ont été touchés ne sont pas rentrés. Il faut blinder là où les données sont": "No return aircraft has an impact on the engines: those affected have not returned. We have to shield where the data are",
