  "La courbe montre le mieux l’évolution et le zigzag des années paires ; les barres comparent les années une à une, depuis zéro, et permettent d’isoler 2024 en couleur ; le tableau coloré garde les valeurs exactes mais demande plus d’effort. Matplotlib : on dit comment dessiner ; Seaborn : bons réglages par défaut à partir d’un tableau ; Altair : on décrit les encodages, et l’infobulle vient presque gratuitement.": "The curve shows the best evolution and zigzag of even years; the bars compare the years one to one, since zero, and allow to isolate 2024 in color; the colored table keeps the exact values but requires more effort. Matplotlib: we say how to draw; Seaborn: good default settings from a table; Altair: we describe encodings, and the infobull comes almost for free.",
