  "Sur 47 217 candidats en 2024, 10 422 ont été déclarés admis (22,1 %), soit 7,1 points de plus qu’en 2023. Avant de conclure, il faut vérifier si la hausse vaut pour toutes les séries et toutes les wilayas.": "Of 47 217 candidates in 2024, 10 422 passed (22,1 %), up 7,1 percentage points from 2023. Before drawing a conclusion, check whether the increase holds across all streams and wilayas.",
