  "À 1 avis minimum,": "At minimum 1 review,",
  "À 1 avis minimum, 57 lieux ont 5,0. À 20 avis, presque aucun. Pourquoi ?": "At a minimum of 1 review, 57 locations have 5,0. At 20 reviews, almost none. Why?",
  "À 10 %, le facteur vaut 1,83. Le mensonge commence bien avant.": "At 10%, the factor is worth 1,83. The lie starts long before.",
  "À 12 fuseaux, les formes sont presque justes. Pourquoi n’utilise-t-on pas cette carte ?": "At 12 spindles, the shapes are almost right. Why don't we use this map?",
  "À 5 %, le facteur vaut déjà 1,29 : la baisse paraît 29 % plus forte qu’elle n’est.": "At 5%, the factor is already 1,29: the drop appears to be 29% higher than it is.",
  "À Guidimagha, dans une classe de 30, combien d’élèves ont eu le bac en 2025 ?": "In Guidimagha, in a class of 30, how many students had the baccalaureate in 2025?",
  "À cette échelle, 1 km fait moins d’un pixel. La généralisation du CM n’est pas qu’un choix de lecture : elle sert aussi la vitesse.": "At this scale, 1 km is less than one pixel. The generalisation of CM is not only a choice of reading: it also serves speed.",
  "À chaque appel, D3 compare les données aux éléments : les nouvelles entrent, les présentes se mettent à jour, celles qui manquent sortent. C’est ce qui permet d’animer un graphique quand les données changent, et de répondre à un clic.": "At each call, D3 compares the data with the elements: the news enters, the present updates, the missing ones exits. That's what makes it possible to animate a graph when the data changes, and to respond to a click.",
